#include "core/shaders/common/lighting.glsl"
#include "core/shaders/common/noise.glsl"
#include "core/shaders/common/fx.glsl"
#include "core/shaders/common/vfx_composite.glsl"

uniform vec4      u_baseColor;
uniform float     u_translucency;
uniform float     u_rimStrength;
uniform float     u_fresnelPower;
uniform float     u_emissiveIntensity;
uniform int       u_hasTexture1;
uniform sampler2D texture1;
uniform float     u_dissolve;
uniform float     u_vfxBodyOpacity;
uniform vec4      u_vfxEmissionColor;
uniform float     u_vfxEmissionIntensity;
uniform float     u_vfxCoreMask;
uniform vec3      u_lightDirView;

void main() {
    vec3 normal = normalize(fragNormal);
#if defined(OUTPUT_BODY) || defined(OUTPUT_EMISSION) || defined(OUTPUT_PREMULTIPLIED)
    // The opt-in path uses one coordinate contract: VS output, view vector and
    // sun direction are all view-space. Legacy output stays byte-for-byte on
    // its old convention until individual VFX are deliberately migrated.
    vec3 viewDir = normalize(-fragPosition);
    vec3 lightDir = normalize(u_lightDirView);
#else
    vec3 viewDir = normalize(viewPos - fragPosition);
    vec3 lightDir = normalize(u_lightDir);
#endif

    float diffuse = calcDiffuse(normal, lightDir, 0.2);
    float fresnel = calcFresnel(normal, viewDir, u_fresnelPower);

    vec3 baseColor = u_baseColor.rgb * diffuse;
    if (u_hasTexture1 != 0) {
        // Luminance-only mask (not detail.rgb) — texture1 is meant to modulate
        // brightness. Using Triplanar Mapping to avoid UV distortion on 
        // procedural meshes (spheres, rocks) and ensure seamless tiling.
        vec3 triBlend = abs(normal);
        triBlend /= (triBlend.x + triBlend.y + triBlend.z + 0.0001);
        
        float texScale = 2.0; // Scale lặp lại texture nhiều hơn để dễ thấy
        float maskX = texture(texture1, fragPosition.zy * texScale).r;
        float maskY = texture(texture1, fragPosition.xz * texScale).r;
        float maskZ = texture(texture1, fragPosition.xy * texScale).r;
        
        float detailMask = maskX * triBlend.x + maskY * triBlend.y + maskZ * triBlend.z;
        
        // Đảm bảo không bao giờ đen thui ngay cả khi detailMask = 0
        baseColor = baseColor * mix(0.5, 2.0, detailMask);
    }

#if !defined(OUTPUT_BODY) && !defined(OUTPUT_EMISSION) && !defined(OUTPUT_PREMULTIPLIED)
    // Compatibility path used by Material_LoadCustom and all existing presets.
    baseColor += baseColor * u_emissiveIntensity;
