        baseColor, 1.0, outputCoverage,
        u_vfxEmissionColor.rgb, clamp(u_vfxCoreMask, 0.0, 1.0),
        max(u_vfxEmissionIntensity, 0.0));
#else
    finalColor = VFX_ResolveBody(baseColor, 1.0, alpha);
#endif
}
